class Simulation{
    constructor(){
        this.particles = [];
        this.bottle = new Bottle();
        this.glass = new Glass();

        this.INTERACTION_RADIUS = 22;
        this.VELOCITY_DAMPING = 0.99;
        this.GRAVITY = new Vector2(0, 1);
        this.REST_DENSITY = 10;
        this.K_NEAR = 3;
        this.K = 0.5;

        // viscosity (beer is a bit thicker than water)
        this.SIGMA = 0.3;
        this.BETA = 0.1;

        // container collision
        this.PARTICLE_RADIUS = 5;

        // foam
        this.FOAM_GRAVITY = new Vector2(0, -0.6);  // buoyant: floats upward
        this.FOAM_SPEED_THRESH = 5.0;
        this.FOAM_SPAWN_PROB = 0.05;
        this.MAX_FOAM = 600;
        this.FOAM_LIFE_MIN = 12;
        this.FOAM_LIFE_MAX = 30;

        this.fluidHashGrid = new FluidHashGrid(this.INTERACTION_RADIUS);

        // glass sits lower-center, leaning ~45deg
        this.glass.position = new Vector2(canvas.width / 2, canvas.height / 2 + 90);
        this.glass.angle = Math.PI / 4;

        // bottle starts upright and full, above-left of the glass
        this.bottle.position = new Vector2(canvas.width / 2 - 280, canvas.height / 2 - 150);
        this.bottle.angle = 0;

        this.fillBottle();
        this.fluidHashGrid.initialize(this.particles);
    }

    fillBottle(){
        let spacing = 7;
        let b = this.bottle;
        for(let lx = -b.wB + spacing; lx < b.wB - 2; lx += spacing){
            for(let ly = b.bodyTop + spacing; ly < b.bottom - 2; ly += spacing){
                this.particles.push(new Particle(b.localToWorld(new Vector2(lx, ly))));
            }
        }
    }

    // user control: move bottle, dragging the beer inside with it
    setBottlePosition(newPos){
        newPos = new Vector2(newPos.x, newPos.y);
        if(newPos.x < 60) newPos.x = 60;
        if(newPos.x > canvas.width - 60) newPos.x = canvas.width - 60;
        if(newPos.y < 60) newPos.y = 60;
        if(newPos.y > canvas.height - 60) newPos.y = canvas.height - 60;

        let delta = Sub(newPos, this.bottle.position);
        this.bottle.position = newPos;
        for(let i = 0; i < this.particles.length; i++){
            let p = this.particles[i];
            if(this.bottle.isInside(p.position)){
                p.position = Add(p.position, delta);
                p.prevPosition = Add(p.prevPosition, delta);
            }
        }
    }

    // user control: rotate bottle, rotating the beer inside with it
    rotateBottle(deltaAngle){
        this.bottle.angle += deltaAngle;
        let pivot = this.bottle.position;
        let cos = Math.cos(deltaAngle), sin = Math.sin(deltaAngle);
        for(let i = 0; i < this.particles.length; i++){
            let p = this.particles[i];
            if(this.bottle.isInside(p.position)){
                let d = Sub(p.position, pivot);
                p.position = Add(pivot, new Vector2(d.x * cos - d.y * sin, d.x * sin + d.y * cos));
                let dp = Sub(p.prevPosition, pivot);
                p.prevPosition = Add(pivot, new Vector2(dp.x * cos - dp.y * sin, dp.x * sin + dp.y * cos));
            }
        }
    }

    neighbourSearch(){
        this.fluidHashGrid.clearGrid();
        this.fluidHashGrid.mapParticleToCell();
    }

    update(dt){
        this.neighbourSearch();

        this.applyGravity(dt);
        this.viscosity(dt);
        this.predictPositions(dt);
        this.doubleDensityRelaxation(dt);

        this.containerCollisions();

        this.computeNextVelocity(dt);

        this.generateFoam(dt);
        this.cleanup();
    }

    applyGravity(dt){
        for(let i = 0; i < this.particles.length; i++){
            let p = this.particles[i];
            let g = p.isFoam ? this.FOAM_GRAVITY : this.GRAVITY;
            p.velocity = Add(p.velocity, Scale(g, dt));
        }
    }

    containerCollisions(){
        for(let i = 0; i < this.particles.length; i++){
            let p = this.particles[i];
            this.bottle.collide(p, this.PARTICLE_RADIUS);
            this.glass.collide(p, this.PARTICLE_RADIUS);
        }
    }

    predictPositions(dt){
        for(let i = 0; i < this.particles.length; i++){
            this.particles[i].prevPosition = this.particles[i].position.Cpy();
            let dpos = Scale(this.particles[i].velocity, dt * this.VELOCITY_DAMPING);
            this.particles[i].position = Add(this.particles[i].position, dpos);
        }
    }

    computeNextVelocity(dt){
        for(let i = 0; i < this.particles.length; i++){
            let v = Scale(Sub(this.particles[i].position, this.particles[i].prevPosition), 1.0 / dt);
            this.particles[i].velocity = v;
        }
    }

    viscosity(dt){
        for(let i = 0; i < this.particles.length; i++){
            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
            let particleA = this.particles[i];

            for(let j = 0; j < neighbours.length; j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB) continue;

                let rij = Sub(particleB.position, particleA.position);
                let q = rij.Length() / this.INTERACTION_RADIUS;

                if(q < 1){
                    rij.Normalize();
                    let u = Sub(particleA.velocity, particleB.velocity).Dot(rij);

                    if(u > 0){
                        let ITerm = dt * (1 - q) * (this.SIGMA * u + this.BETA * u * u);
                        let I = Scale(rij, ITerm);
                        particleA.velocity = Sub(particleA.velocity, Scale(I, 0.5));
                        particleB.velocity = Add(particleB.velocity, Scale(I, 0.5));
                    }
                }
            }
        }
    }

    doubleDensityRelaxation(dt){
        for(let i = 0; i < this.particles.length; i++){
            let density = 0;
            let densityNear = 0;
            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
            let particleA = this.particles[i];

            for(let j = 0; j < neighbours.length; j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB) continue;

                let rij = Sub(particleB.position, particleA.position);
                let q = rij.Length() / this.INTERACTION_RADIUS;

                if(q < 1){
                    let oneMinusQ = (1 - q);
                    density += oneMinusQ * oneMinusQ;
                    densityNear += oneMinusQ * oneMinusQ * oneMinusQ;
                }
            }

            let pressure = this.K * (density - this.REST_DENSITY);
            let pressureNear = this.K_NEAR * densityNear;
            let particleADisplacement = Vector2.Zero();

            particleA.density = density;

            for(let j = 0; j < neighbours.length; j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB) continue;

                let rij = Sub(particleB.position, particleA.position);
                let q = rij.Length() / this.INTERACTION_RADIUS;

                if(q < 1.0){
                    rij.Normalize();
                    let displacementTerm = Math.pow(dt, 2) *
                        (pressure * (1 - q) + pressureNear * Math.pow(1 - q, 2));
                    let D = Scale(rij, displacementTerm);

                    particleB.position = Add(particleB.position, Scale(D, 0.5));
                    particleADisplacement = Sub(particleADisplacement, Scale(D, 0.5));
                }
            }
            particleA.position = Add(particleA.position, particleADisplacement);
        }
    }

    // spawn buoyant foam where the beer is agitated (fast-moving), then age & cull
    generateFoam(dt){
        let foamCount = 0;
        for(let i = 0; i < this.particles.length; i++){
            if(this.particles[i].isFoam) foamCount++;
        }

        let n = this.particles.length;
        for(let i = 0; i < n; i++){
            let p = this.particles[i];
            if(p.isFoam) continue;
            let speed = p.velocity.Length();
            if(speed > this.FOAM_SPEED_THRESH && foamCount < this.MAX_FOAM && Math.random() < this.FOAM_SPAWN_PROB){
                let f = new Particle(p.position.Cpy());
                f.prevPosition = f.position.Cpy();
                f.isFoam = true;
                f.foamLife = this.FOAM_LIFE_MIN + Math.random() * (this.FOAM_LIFE_MAX - this.FOAM_LIFE_MIN);
                f.velocity = new Vector2((Math.random() - 0.5) * 8, -8 - Math.random() * 8);
                this.particles.push(f);
                foamCount++;
            }
        }

        for(let i = this.particles.length - 1; i >= 0; i--){
            let p = this.particles[i];
            if(p.isFoam){
                p.foamLife -= dt;
                if(p.foamLife <= 0) this.particles.splice(i, 1);
            }
        }
    }

    // cull particles that fell off the table
    cleanup(){
        for(let i = this.particles.length - 1; i >= 0; i--){
            let p = this.particles[i];
            if(p.position.y > canvas.height + 120 ||
               p.position.x < -120 || p.position.x > canvas.width + 120){
                this.particles.splice(i, 1);
            }
        }
    }

    drawFluid(targetCtx, radius, sprite, typeFilter){
        let d = radius * 2;
        for(let i = 0; i < this.particles.length; i++){
            let p = this.particles[i];
            if(typeFilter === "beer" && p.isFoam) continue;
            if(typeFilter === "foam" && !p.isFoam) continue;
            targetCtx.drawImage(sprite, p.position.x - radius, p.position.y - radius, d, d);
        }
    }

    draw(){
        this.glass.drawOutline();
        this.bottle.drawOutline();
    }
}

