class Playground{
    constructor(){
        this.simulation = new Simulation();
        this.keys = {};
        this.rotSpeed = 0.03;
    }

    update(dt){
        this.simulation.update(0.25);
        if(this.keys['q']) this.simulation.rotateBottle(-this.rotSpeed);
        if(this.keys['w']) this.simulation.rotateBottle( this.rotSpeed);
    }

    drawFluid(targetCtx, radius, sprite, typeFilter){
        this.simulation.drawFluid(targetCtx, radius, sprite, typeFilter);
    }

    draw(){
        this.simulation.draw();
    }

    onMouseMove(position){
        this.simulation.setBottlePosition(position);
    }

    onMouseDown(button){}
    onMouseUp(button){}

    onKeyDown(key){ this.keys[key] = true; }
    onKeyUp(key){ this.keys[key] = false; }
}

