const { chromium } = require("/home/sprite/project/fluid-simulation/node_modules/playwright-core");

(async () => {
  const file = process.argv[2];
  const out  = process.argv[3] || "/tmp/shot.png";
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 960, height: 700 } });
  const errors = [];
  page.on("pageerror", e => errors.push("PAGEERROR: " + e.message));
  page.on("console", m => { if (m.type() === "error") errors.push("CONSOLE: " + m.text()); });

  await page.goto("file://" + file);
  await page.waitForTimeout(300);
  // tilt the bottle to pour (press E for a while), also slosh near the end
  await page.keyboard.down("e");
  await page.waitForTimeout(2500);
  await page.keyboard.up("e");
  await page.waitForTimeout(600);
  await page.keyboard.down("d");
  await page.waitForTimeout(500);
  await page.keyboard.up("d");
  await page.waitForTimeout(400);

  await page.screenshot({ path: out });
  console.log(errors.length ? errors.join("\n") : "NO_JS_ERRORS");
  await browser.close();
})();

